package com.plantgrowth.forecasting.controller;
import com.plantgrowth.forecasting.dto.Contracts.*;import com.plantgrowth.forecasting.entity.*;import com.plantgrowth.forecasting.repository.*;import com.plantgrowth.forecasting.service.GuestAccessService;import jakarta.validation.Valid;import java.io.IOException;import java.nio.file.*;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.util.StringUtils;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/plants") public class PlantController {final PlantRepository plants;final GrowthRecordRepository growth;final SoilRecordRepository soils;final GuestAccessService guest;final Path uploadDir;PlantController(PlantRepository p,GrowthRecordRepository g,SoilRecordRepository s,GuestAccessService guest,@Value("${app.upload-dir:uploads}") String dir){plants=p;growth=g;soils=s;this.guest=guest;uploadDir=Path.of(dir).toAbsolutePath().normalize();}Plant owned(Long id,Long uid){return plants.findByIdAndOwnerId(id,uid).orElseThrow(()->new IllegalArgumentException("Plant not found or access denied"));}PlantView view(Plant p){return new PlantView(p.getId(),p.getPlantCode(),p.getPlantName(),p.getSpecies(),p.getPlantingDate(),p.getLocation().getLocationName(),p.getImageUrl());}SoilView soilView(SoilRecord s){return new SoilView(s.getId(),s.getObservationDate(),s.getSoilPh(),s.getSoilMoisture(),s.getNitrogen(),s.getPhosphorus(),s.getPotassium(),s.getSource());}@GetMapping List<PlantView> list(@AuthenticationPrincipal Long uid){return plants.findByOwnerIdAndStatus(uid,Status.ACTIVE).stream().map(this::view).toList();}@PostMapping @Transactional ResponseEntity<PlantView> create(@AuthenticationPrincipal Long uid,@Valid @RequestBody PlantInput x){guest.requireWritable(uid);Plant p=new Plant();p.setOwner(new UserRef(uid).toEntity());p.setPlantCode(x.plantCode());p.setPlantName(x.plantName());p.setSpecies(x.species());p.setPlantingDate(x.plantingDate());GrowingLocation l=new GrowingLocation();l.setLocationName(x.locationName());p.setLocation(l);return ResponseEntity.status(201).body(view(plants.save(p)));}@PostMapping(value="/{id}/image",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @Transactional ImageView uploadImage(@AuthenticationPrincipal Long uid,@PathVariable Long id,@RequestPart("file") MultipartFile file)throws IOException{guest.requireWritable(uid);Plant p=owned(id,uid);if(file.isEmpty()||file.getSize()>5000000)throw new IllegalArgumentException("Choose an image smaller than 5 MB");String type=Optional.ofNullable(file.getContentType()).orElse("");if(!List.of("image/jpeg","image/png","image/webp").contains(type))throw new IllegalArgumentException("Only JPG, PNG, or WebP images are supported");Path folder=uploadDir.resolve("plants");Files.createDirectories(folder);String ext=StringUtils.getFilenameExtension(Optional.ofNullable(file.getOriginalFilename()).orElse("jpg"));String name=UUID.randomUUID()+"."+(ext==null?"jpg":ext.toLowerCase(Locale.ROOT));file.transferTo(folder.resolve(name));p.setImageUrl("/uploads/plants/"+name);return new ImageView(p.getImageUrl());}@GetMapping("/{id}") PlantView get(@AuthenticationPrincipal Long uid,@PathVariable Long id){return view(owned(id,uid));}@PutMapping("/{id}") @Transactional PlantView update(@AuthenticationPrincipal Long uid,@PathVariable Long id,@Valid @RequestBody PlantInput x){guest.requireWritable(uid);Plant p=owned(id,uid);p.setPlantCode(x.plantCode());p.setPlantName(x.plantName());p.setSpecies(x.species());p.setPlantingDate(x.plantingDate());p.getLocation().setLocationName(x.locationName());return view(p);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @Transactional void archive(@AuthenticationPrincipal Long uid,@PathVariable Long id){guest.requireWritable(uid);owned(id,uid).setStatus(Status.ARCHIVED);}@GetMapping("/{id}/growth-records") List<GrowthView> records(@AuthenticationPrincipal Long uid,@PathVariable Long id){owned(id,uid);return growth.findByPlantIdOrderByMeasurementTimestampAsc(id).stream().map(g->new GrowthView(g.getId(),g.getMeasurementTimestamp(),g.getPlantHeightCm())).toList();}@PostMapping("/{id}/growth-records") @Transactional ResponseEntity<GrowthView> add(@AuthenticationPrincipal Long uid,@PathVariable Long id,@Valid @RequestBody GrowthInput x){guest.requireWritable(uid);GrowthRecord g=new GrowthRecord();g.setPlant(owned(id,uid));g.setMeasurementTimestamp(x.measurementTimestamp());g.setPlantHeightCm(x.plantHeightCm());g.setMeasurementMethod(x.measurementMethod());g.setSource(x.source());g=growth.save(g);return ResponseEntity.status(201).body(new GrowthView(g.getId(),g.getMeasurementTimestamp(),g.getPlantHeightCm()));}@GetMapping("/{id}/soil-records") List<SoilView> soil(@AuthenticationPrincipal Long uid,@PathVariable Long id){owned(id,uid);return soils.findByPlantIdOrderByObservationDateDesc(id).stream().map(this::soilView).toList();}@PostMapping("/{id}/soil-records") @Transactional ResponseEntity<SoilView> addSoil(@AuthenticationPrincipal Long uid,@PathVariable Long id,@Valid @RequestBody SoilInput x){guest.requireWritable(uid);Plant p=owned(id,uid);SoilRecord s=new SoilRecord();s.setPlant(p);s.setLocation(p.getLocation());s.setObservationDate(x.observationDate());s.setSoilPh(x.soilPh());s.setSoilMoisture(x.soilMoisture());s.setNitrogen(x.nitrogen());s.setPhosphorus(x.phosphorus());s.setPotassium(x.potassium());s.setSource(x.source());return ResponseEntity.status(201).body(soilView(soils.save(s)));}static class UserRef{Long id;UserRef(Long i){id=i;}User toEntity(){User u=new User();try{var f=User.class.getDeclaredField("id");f.setAccessible(true);f.set(u,id);}catch(Exception e){throw new IllegalStateException(e);}return u;}}}
